import { ProfileContextConflict } from '../../storage/profiles/contextReceipts';
import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import type { DesignLibraryReference } from '../../types/design-library';

export interface ResolvedReferenceKey {
  key: string;
  reference: DesignLibraryReference;
}

export const resolveReferenceKeys = (
  records: Pick<ProfileRecords, 'libraryReferences'>,
  keys: string[],
): ResolvedReferenceKey[] | null => {
  const identities = [...new Set(keys)].map((key) => {
    const [prefix, revision] = key.split('@');
    return { key, prefix, revision: Number(revision) };
  });
  const candidates = records.libraryReferences(
    identities.map((identity) => identity.prefix),
  );
  const selected: ResolvedReferenceKey[] = [];
  const seen = new Set<string>();
  for (const identity of identities) {
    const matches = candidates.filter((reference) =>
      reference.id.startsWith(identity.prefix),
    );
    if (matches.length > 1)
      throw new ProfileContextConflict(
        'Reference key is ambiguous. Copy the selection again from Design library.',
      );
    const reference = matches[0];
    if (!reference) return null;
    if (reference.revision !== identity.revision)
      throw new ProfileContextConflict(
        'A saved reference has changed. Copy the selection again from Design library.',
      );
    if (seen.has(reference.id)) continue;
    seen.add(reference.id);
    selected.push({ key: identity.key, reference });
  }
  return selected;
};
